import React from 'react';
import {AbsoluteFill,interpolate,Easing,clamp,useS,en,FONT} from './kit';
const CY='#74e9ff', VI='#9d77ff', GL='#f9cd75';
const stops=[en('ojos'),en('cerebro'),en('color'),en('longitudes'),en('rojo'),en('azul'),en('realidad'),en('mente')];
const nodes=[
 {title:'LA LUZ',detail:'EL ORIGEN',col:GL,kind:0},
 {title:'TUS OJOS',detail:'RECIBEN FOTONES',col:CY,kind:1},
 {title:'CEREBRO',detail:'INTERPRETA SEÑALES',col:VI,kind:2},
 {title:'COLOR',detail:'UNA EXPERIENCIA',col:GL,kind:3},
 {title:'LONGITUDES',detail:'DE ONDA',col:CY,kind:4},
 {title:'ROJO',detail:'ONDA MÁS LARGA',col:'#ff6b80',kind:5},
 {title:'AZUL',detail:'ONDA MÁS CORTA',col:'#74b8ff',kind:6},
 {title:'REALIDAD',detail:'CREADA EN TU MENTE',col:GL,kind:7},
 {title:'VARIADO',detail:'LO INCREÍBLE ES REAL',col:CY,kind:8}
];
const path=(x:number)=>880+Math.sin(x*.004)*110;
const ease=(s:number,a:number,b:number)=>interpolate(s,[a,b],[0,1],clamp);
export const SUBS={arriba:1670,size:46,acento:GL};
export const Escena:React.FC=()=>{
 const {s}=useS();
 const z=stops.reduce((v,t,i)=>s>=t?(i+1):v,0);
 const start=z===0?0:stops[z-1],end=stops[Math.min(z,stops.length-1)]||start+3;
 const p=ease(s,start,Math.max(start+.01,end));
 const camera=(Math.min(z,8)+p)*1080;
 const dust=Array.from({length:42},(_,i)=>({x:(i*337)%1080,y:(i*583)%1920,r:2+i%4}));
 return <AbsoluteFill style={{background:'radial-gradient(circle at 50% 45%,#17243b 0%,#090d1a 50%,#03050b 100%)',overflow:'hidden',fontFamily:FONT}}>
 <AbsoluteFill style={{background:'radial-gradient(circle at 50% 25%,rgba(103,144,216,.15),transparent 60%)'}}/>
 {dust.map((v,i)=><div key={i} style={{position:'absolute',left:v.x+Math.sin(s*.32+i)*22,top:v.y+Math.cos(s*.26+i)*18,width:v.r,height:v.r,background:i%3===0?GL:CY,opacity:.13+(i%5)*.055,borderRadius:'50%'}}/>)}
 <div style={{position:'absolute',top:70,left:64,letterSpacing:7,color:'#8daac6',fontWeight:800,fontSize:29}}>VARIADO / UNA PREGUNTA IMPOSIBLE</div>
 <AbsoluteFill style={{transform:'translateY('+(-camera)+'px)'}}>
 <svg viewBox="0 0 1080 12000" width="1080" height="12000" style={{position:'absolute',top:0,left:0}}>
 <defs><linearGradient id="ray" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#f9cd75"/><stop offset=".5" stopColor="#74e9ff"/><stop offset="1" stopColor="#9d77ff"/></linearGradient><filter id="blur"><feGaussianBlur stdDeviation="22"/></filter></defs>
 <path d={'M 540 880 '+Array.from({length:8},(_,i)=>'C '+(250+i%2*580)+' '+(950+i*1080)+' '+(830-i%2*580)+' '+(1270+i*1080)+' 540 '+(1960+i*1080)).join(' ')} stroke="url(#ray)" strokeWidth="54" fill="none" opacity=".20" filter="url(#blur)"/>
 <path d={'M 540 880 '+Array.from({length:8},(_,i)=>'C '+(250+i%2*580)+' '+(950+i*1080)+' '+(830-i%2*580)+' '+(1270+i*1080)+' 540 '+(1960+i*1080)).join(' ')} stroke="url(#ray)" strokeWidth="8" fill="none" strokeLinecap="round"/>
 </svg>
 {nodes.map((n,i)=>{const y=860+i*1080;const near=Math.max(0,1-Math.abs((camera/1080)-i)*.72);const pulse=Math.sin(s*2+i)*.025;
 return <React.Fragment key={i}>
 <div style={{position:'absolute',top:y-280,left:140,width:800,height:800,borderRadius:'50%',border:'2px solid '+n.col,opacity:near*.26,boxShadow:'0 0 130px '+n.col+'30, inset 0 0 110px '+n.col+'18',transform:'perspective(1100px) rotateX(56deg) rotateY('+((i%2?1:-1)*16)+'deg) scale('+(1+pulse)+')'}}/>
 <div style={{position:'absolute',top:y-120,left:280,width:520,height:520,borderRadius:'50%',background:'radial-gradient(circle at 30% 25%, #ffffff 0%, '+n.col+' 16%, #152c48 69%, #060e21 100%)',boxShadow:'0 15px 100px '+n.col+'55, inset -18px -25px 50px rgba(0,0,0,.5)',opacity:Math.min(1,near+.28),transform:'scale('+(0.8+near*.2)+')'}}/>
 <div style={{position:'absolute',top:y+440,width:1080,textAlign:'center',color:'#f5f7ff',fontSize:88,fontWeight:900,letterSpacing:1,textShadow:'0 10px 50px #02020b'}}>{n.title}</div>
 <div style={{position:'absolute',top:y+555,width:1080,textAlign:'center',color:n.col,fontSize:31,fontWeight:700,letterSpacing:7}}>{n.detail}</div>
 {Array.from({length:6},(_,j)=><div key={j} style={{position:'absolute',top:y+70+Math.sin(s*(.6+j*.03)+j)*125,left:540+Math.cos(j*Math.PI/3+s*.14)*350,width:18,height:18,borderRadius:'50%',background:n.col,opacity:.5*near,boxShadow:'0 0 22px '+n.col}}/>)}
 </React.Fragment>})}
 </AbsoluteFill>
 <div style={{position:'absolute',top:260,left:70,right:70,textAlign:'center',fontSize:37,fontWeight:800,color:'#f7d991',letterSpacing:3,opacity:Math.max(0,1-ease(s,0.8,2))}}>¿Y SI LOS COLORES NO EXISTEN COMO CREES?</div>
 <div style={{position:'absolute',bottom:245,left:84,right:84,height:3,background:'#9dabc144'}}><div style={{height:3,width:(100*Math.min(1,s/(stops[7]+2)))+'%',background:GL}}/></div>
 </AbsoluteFill>
};
